import React, { useState, useEffect } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import Header from "../components/header";
import Footer from "../components/footer";

const Results = () => {
  const location = useLocation();
  const navigate = useNavigate();

  const products = location.state?.products || [];
  const [sortBy, setSortBy] = useState("default");

  const [favorites, setFavorites] = useState([]);
  const [user, setUser] = useState(null);

  // ================= USER LOAD =================
  useEffect(() => {
    const storedUser = JSON.parse(localStorage.getItem("user"));
    setUser(storedUser);
  }, []);

  // ================= FAVORITES LOAD =================
  useEffect(() => {
    if (!user) return;

    fetch(`http://localhost:5000/favorites/${user.email}`)
      .then((res) => res.json())
      .then((data) => setFavorites(data))
      .catch((err) => console.log(err));
  }, [user]);

  // ================= CHECK FAVORITE =================
  const isFavorite = (product) => {
    return favorites.some((item) => item.link === product.link);
  };

  // ================= TOAST =================
  const showToast = (message) => {
    const toast = document.createElement("div");
    toast.innerText = message;
    toast.className = "toast";
    document.body.appendChild(toast);
    setTimeout(() => toast.remove(), 2000);
  };

  // ================= FAVORITE TOGGLE =================
  const toggleFavorite = async (product) => {
    if (!user) {
      showToast("⚠️ Please Sign In first!");
      return;
    }

    try {
      const existing = favorites.find(
        (item) => item.link === product.link
      );

      if (existing) {
        await fetch(
          `http://localhost:5000/favorites/${existing._id}`,
          { method: "DELETE" }
        );

        const updated = favorites.filter(
          (item) => item.link !== product.link
        );

        setFavorites(updated);
        showToast("Removed from favorites ❌");
      } else {
        const response = await fetch(
          "http://localhost:5000/favorites",
          {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
              userEmail: user.email,
              title: product.title,
              price: product.price,
              rating: product.rating,
              image: product.thumbnail || product.image, // ✅ FIX
              link: product.link,
              source: product.source,
            }),
          }
        );

        const data = await response.json();
        setFavorites([...favorites, { ...product }]);

        showToast("Added to favorites ⭐");
      }
    } catch (error) {
      console.log(error);
    }
  };

  // ================= SORT =================
  const sorted = [...products].sort((a, b) => {
    if (sortBy === "price-low") {
      return (
        (parseFloat(a.price?.replace(/[^0-9.]/g, "")) || 9999) -
        (parseFloat(b.price?.replace(/[^0-9.]/g, "")) || 9999)
      );
    }

    if (sortBy === "price-high") {
      return (
        (parseFloat(b.price?.replace(/[^0-9.]/g, "")) || 0) -
        (parseFloat(a.price?.replace(/[^0-9.]/g, "")) || 0)
      );
    }

    if (sortBy === "rating") {
      return (parseFloat(b.rating) || 0) - (parseFloat(a.rating) || 0);
    }

    return 0;
  });

  return (
    <>
      <Header />

      <div style={{ padding: "20px" }}>
        <h2>Results</h2>
        <p>Search found: {products.length} products</p>

        {/* SORT */}
        <div style={{ marginBottom: "15px" }}>
          <button onClick={() => setSortBy("price-low")}>Low Price</button>
          <button onClick={() => setSortBy("price-high")}>High Price</button>
          <button onClick={() => setSortBy("rating")}>Top Rated</button>
        </div>

        {/* PRODUCTS */}
        <div className="products-grid">
          {sorted.map((product, index) => (
            <div className="product-card" key={index}>
              
              {/* IMAGE FIX */}
              {product.thumbnail || product.image ? (
                <img
                  src={product.thumbnail || product.image}
                  alt={product.title}
                  className="product-img"
                />
              ) : (
                <div className="no-img">🛍️</div>
              )}

              <h3>{product.title}</h3>

              <p><b>Price:</b> {product.price}</p>
              <p><b>Rating:</b> {product.rating}</p>
              <p><b>Source:</b> {product.source}</p>

              <div style={{ display: "flex", gap: "10px" }}>
                
                {/* FAVORITE */}
                <button onClick={() => toggleFavorite(product)}>
                  {isFavorite(product) ? "★" : "☆"}
                </button>

                {/* VISIT WEBSITE FIX */}
                <button
                  onClick={() => {
                    if (product.link && product.link !== "#") {
                      window.open(product.link, "_blank"); // ✅ FIX
                    } else {
                      alert("Link not available");
                    }
                  }}
                >
                  Visit →
                </button>

              </div>
            </div>
          ))}
        </div>
      </div>

      <Footer />
    </>
  );
};

export default Results;
